import { Link } from "react-router-dom";

function Navbar() {
  return (
    <nav className="nav">
      <h2>Citizens Voice</h2>
      <div>
        <Link to="/">Home</Link>
        <Link to="/add">Add</Link>
        <Link to="/track">Track</Link>
        <Link to="/admin">Admin</Link>
      </div>
    </nav>
  );
}
export default Navbar;
